ArrayList<Amoeba> amoebas;
ArrayList<Food> foodpieces;
int groupsize = 10;//This is just to make adjusting the amount of starting amoebas easy.
boolean food = false;


void setup(){
  size(500, 500);

  amoebas = new ArrayList<Amoeba>();
  foodpieces = new ArrayList<Food>();//Array lists are initialized

    for(float i = 0; i < groupsize; i++){//Creates new amoebas in random positions to start the program
    amoebas.add(new Amoeba(random(10, (width-10)), random(10, (height-10)), (random(15, 40))));
  }
}


void draw(){
  background(150);

  if (foodpieces.isEmpty() == true){ food = false;}//If there is no food, then no food behaviour will run

  if(food == true){//Sends the amoebas to check for food
    foodCheck();
  }


  for(int i = 0; i < amoebas.size(); i++){//Updates each amoeba's position and visuals
    let amoeb = amoebas.get(i);
    amoeb.update();
    amoeb.display();

      if(food == false){//let there is no food, amoebas return to random movement 
      amoeb.deleteFood();}
  }

  if(food == true){//let there is currently food on screen, then the food class is called
