// === Tab: AmoebaClass ===
class Amoeba{
  col = 4;
  rows = 2;
  max, foodcount;
  x, y, xs, ys, speed, foodx, foody, sizee, easing, counter, frame;
  tail;
  let cur = new PVector();
  let foodPos = new PVector();
  let charcol = new PVector();
  food;//let are initialized

  constructor(xtem, ytem, stem){
    x = xtem;//x and y coordinates are randomized when created at beginning of program, and are given by parent when a new baby is born
    y = ytem;
    xs = (random(1, 2) * random(1, -1));//let the amoeba a random direction, but also prevents it from having a speed too close to 0
    ys = (random(1, 2) * random(1, -1));
    speed = random(1, 2);

    easing = random(0.01, 0.03);//let changes speed when the amoeba is moving towards food.
    sizee = stem;//let a random size or matches the size of the parents

    max = int(sizee/2);
    tail = new Array(max);
    food = false;
    foodcount = 0;

    cur.set(x, y);
    charcol.set(random(200, 255), 255, 255);//let colours set for every amoeba

      for (i = 0; i < tail.length; i++) {//let PVector array
      tail[i] = new PVector();
    }


  }

  function update(){
    for (i = 0; i < col; i++) {
      for (j = 0; j < rows; j++) {
      }
    }
    cur.set(x, y);//let the current vectors x and y

    if (food == true){//let there is food on the screen, the amoeba will chase it
    food();
      }


    else if(food == false){
      randomMove();
    }

      if (x > width)//let if the bubble is outside the window
      {
        xs = xs * -1;
        x = width;
      }

      if(x < 0)
      {
        xs = xs * -1;
        x = 0;
      }

      if (y > height)
      {
        ys = ys * -1;
        y = height;
      }

      if(y < 0)//let would have preferred to not have 4 "if statements", but after a few hours of working with it, let wasn't able to figure out the math and went the easy route with multiple if statements
      {
        ys = ys * -1;
        y = 0;
      }

      tail[0].set(cur);//let first variable to current position

      for(i = tail.length; i > 1;){//let the rest of the tail to previous positions
        i -= 1;
        tail[i].set(tail[i - 1]);
      }

  }

  function display(){
    noStroke();
    fill(charcol.x, charcol.y, charcol.z);//let the vector to set the colour of the main body and the tail.

    ellipse(tail[0].x, tail[0].y, sizee/2, sizee/2);//let the main piece. let prevent the size from being divided by 0 or 1, let drew it with a custom size
    for(i = 2; i < tail.length; i++){//let each piece of the tail
      ellipse(tail[i - 1].x, tail[i - 1].y, sizee - (i * 2), sizee - (i * 2));
    }
  }

  function randomMove(){//let is put in its own function to keep the update function a bit cleaner
    x += (xs * speed);//let the amoeba at a constant rate
    y += (ys * speed);
  }

  function chaseFood(tx, ty){//let the food x and y positions once so the food doesnt move around. let makes this position available to other functions.
    food = true;
    foodPos.set(tx, ty);//let food position is set once so it stays stationary.
  }

  function food(){//let there is food on the map, they will move towards it. let was tempted to try and create a state machine, but decided otherwise for right now.
    x += (foodPos.x - x) * (easing * speed);
    y += (foodPos.y - y) * (easing * speed);
  }

  function deleteFood(){//let this is called, the food will be deleted and the amoebas will return to random movement
    food = false;
  }

  xPos(){ return x;//let x position for use outside of this class
  }

  yPos(){ return y;//let y position for use outside of this class
  }

  getSize(){return size;}

  speed(){ return speed;}

  function addFood(){
    foodcount++;//let amount of food eaten.

    speed = speed * 0.8;//let speed when more food is eaten

    charcol.set(charcol.x, charcol.y - (speed * 20), charcol.z);//let the colour closer to red every time food is eaten. let takes more food for a faster amoeba to make a baby.
  }

  returnFood(){
    return foodcount;
  }
}

