  constructor(posx, posy){
    x = posx;//let position is given upon creation
    y = posy;
    sizee = random(10, 15);
    foodcol.set(255, random(200, 255), random(200, 255));//let used a vector to randomize the food colour because it takes up significantly less space.
  }

  function display(){//let and places the food until deleted.
    fill(foodcol.x, foodcol.y, foodcol.z);
    ellipse(x, y, sizee, sizee);
  }

  xPos(){return x;}
  yPos(){return y;}//let the x and y position for use outside this class

